use crate::position::AccountBalance;

/// Add an observation, keeping every earlier one — unless it is the same account on the same DAY, in
/// which case it is a correction rather than a new observation and replaces it.
pub fn record(balances: &mut Vec<AccountBalance>, next: AccountBalance) {
    match balances.iter_mut().find(|b| b.account == next.account && b.as_of == next.as_of) {
        Some(slot) => *slot = next,
        None => {
            balances.push(next);
            balances.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
        }
    }
}
